(function(){
  'use strict';
  const STATUS_ORDER=['ثبت شده','منتظر پاسخ','در حال انجام','انجام شده'];
  const PRIORITY_ORDER=['فوری','کم','متوسط'];
  const BUCKET_ORDER=['دیرکرد','دوره هشدار','فاقد شرایط دیرکرد'];
  const $id=id=>document.getElementById(id);
  const shortName=name=>{let value=String(name||'').trim();for(const prefix of ['جناب آقای ','سرکار خانم ','مهندس ','آقای ','خانم '])if(value.startsWith(prefix))value=value.slice(prefix.length);return value||'—'};
  const bucketOf=task=>{if(norm(task.status)==='منتظر پاسخ')return'فاقد شرایط دیرکرد';const due=norm(task.due_state);return due==='دیرکرد'?'دیرکرد':due.includes('هشدار')?'دوره هشدار':'فاقد شرایط دیرکرد'};
  const setOptions=(id,values)=>{const el=$id(id);if(!el)return;const old=el.value||'همه';el.innerHTML=values.map(v=>`<option>${safe(v)}</option>`).join('');el.value=values.includes(old)?old:'همه'};
  function refreshFilters(){const rows=state.tasks||[],active=rows.filter(t=>!t.archived);setOptions('dashOwner',['همه',...[...new Set(rows.map(ownerName).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fa'))]);setOptions('dashPriority',['همه',...PRIORITY_ORDER.filter(v=>rows.some(t=>norm(t.priority)===v))]);setOptions('dashStatus',['همه',...STATUS_ORDER.filter(v=>active.some(t=>norm(t.status)===v))]);setOptions('dashBucket',['همه',...BUCKET_ORDER.filter(v=>active.some(t=>bucketOf(t)===v))])}
  function filtered(){let kanban=state.tasks.filter(t=>!t.archived),archive=state.tasks.filter(t=>t.archived);const owner=$id('dashOwner')?.value||'همه',priority=$id('dashPriority')?.value||'همه',status=$id('dashStatus')?.value||'همه',bucket=$id('dashBucket')?.value||'همه';if(owner!=='همه'){kanban=kanban.filter(t=>norm(ownerName(t))===norm(owner));archive=archive.filter(t=>norm(ownerName(t))===norm(owner))}if(priority!=='همه'){kanban=kanban.filter(t=>norm(t.priority)===norm(priority));archive=archive.filter(t=>norm(t.priority)===norm(priority))}if(status!=='همه'){kanban=kanban.filter(t=>norm(t.status)===norm(status));archive=[]}if(bucket!=='همه'){kanban=kanban.filter(t=>bucketOf(t)===norm(bucket));archive=[]}return[kanban,archive]}
  function renderCards(kanban,archive){const active=kanban.filter(t=>norm(t.status)!=='انجام شده'),spec=[['archive_total','کل کارهای آرشیو شده',archive.length],['warning','در دوره هشدار',active.filter(t=>bucketOf(t)==='دوره هشدار').length],['overdue','دارای دیرکرد',active.filter(t=>bucketOf(t)==='دیرکرد').length],['waiting','منتظر پاسخ',active.filter(t=>norm(t.status)==='منتظر پاسخ').length],['in_progress','در حال انجام',active.filter(t=>norm(t.status)==='در حال انجام').length],['total','کل کارهای فعال',active.length]];$id('dashboardCards').innerHTML=spec.map(([key,label,value])=>`<article data-key="${key}"><small>${label}</small><strong>${fa(value)}</strong></article>`).join('')}
  function sizeCanvas(canvas){const dpr=window.devicePixelRatio||1,w=Math.max(700,canvas.parentElement.clientWidth),h=Number(canvas.getAttribute('height')||300);canvas.style.width=`${w}px`;canvas.style.height=`${h}px`;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,w,h}}
  function frame(canvas,title,subtitle=''){const {ctx,w,h}=sizeCanvas(canvas);ctx.clearRect(0,0,w,h);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.direction='rtl';ctx.textAlign='right';ctx.fillStyle='#173f35';ctx.font='bold 21px "B Nazanin",Tahoma';ctx.fillText(title,w-18,31);if(subtitle){ctx.fillStyle='#6a8077';ctx.font='15px "B Nazanin",Tahoma';ctx.fillText(subtitle,w-18,55)}return{ctx,w,h}}
  function empty(canvas,title,message='اطلاعاتی برای نمایش وجود ندارد',subtitle=''){const {ctx,w,h}=frame(canvas,title,subtitle);ctx.textAlign='center';ctx.fillStyle='#7a8e85';ctx.font='18px "B Nazanin",Tahoma';ctx.fillText(message,w/2,h/2)}
  function legend(ctx,w,items,top=78){ctx.textAlign='right';ctx.font='15px "B Nazanin",Tahoma';items.forEach(([label,color],i)=>{const y=top+i*30;ctx.fillStyle=color;ctx.fillRect(w-46,y-10,18,18);ctx.fillStyle='#435b51';ctx.fillText(label,w-54,y+3)})}
  function bar(canvas,title,labels,values,colors){if(!values.length||Math.max(...values)<=0)return empty(canvas,title);const {ctx,w,h}=frame(canvas,title),left=62,right=w-190,top=58,bottom=h-84,max=Math.max(...values);ctx.strokeStyle='#edf2f0';ctx.fillStyle='#879a91';ctx.font='13px "B Nazanin",Tahoma';ctx.textAlign='right';for(let step=0;step<=5;step++){const y=bottom-(bottom-top)*step/5;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillText(fa(Math.round(max*step/5)),left-8,y+4)}const gap=22,bw=Math.max(52,Math.min(120,((right-left)-gap*(values.length+1))/values.length));let x=left+Math.max(0,(right-left-(values.length*bw+(values.length+1)*gap))/2)+gap;labels.forEach((label,i)=>{const bh=(bottom-top-10)*values[i]/max;ctx.fillStyle=colors[i%colors.length];ctx.fillRect(x,bottom-bh,bw,bh);ctx.fillStyle='#435b51';ctx.textAlign='center';ctx.font='bold 15px "B Nazanin",Tahoma';ctx.fillText(fa(values[i]),x+bw/2,bottom-bh-9);ctx.font='13px "B Nazanin",Tahoma';ctx.fillText(label,x+bw/2,bottom+20);x+=bw+gap});legend(ctx,w,labels.map((l,i)=>[l,colors[i%colors.length]]))}
  function pie(canvas,title,data,colors){data=data.filter(([,v])=>v>0);const total=data.reduce((s,[,v])=>s+v,0);if(!total)return empty(canvas,title);const {ctx,w,h}=frame(canvas,title),legendSpace=180,areaRight=Math.max(240,w-legendSpace),size=Math.max(130,Math.min(220,h-92,areaRight-80)),cx=Math.max(48,(areaRight-size)/2)+size/2,cy=64+size/2,r=size/2;let angle=-Math.PI/2;data.forEach(([label,value],i)=>{const extent=2*Math.PI*value/total,mid=angle+extent/2,color=colors[i%colors.length];ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,angle,angle+extent);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();const x1=cx+Math.cos(mid)*r*.9,y1=cy+Math.sin(mid)*r*.9,x2=cx+Math.cos(mid)*r*1.08,y2=cy+Math.sin(mid)*r*1.08,x3=x2+(Math.cos(mid)>=0?22:-22);ctx.strokeStyle='#789089';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.lineTo(x3,y2);ctx.stroke();ctx.fillStyle='#23342d';ctx.textAlign=Math.cos(mid)>=0?'left':'right';ctx.font='bold 13px "B Nazanin",Tahoma';ctx.fillText(`${fa((value/total*100).toFixed(1))}٪ - ${fa(value)}`,x3+(Math.cos(mid)>=0?6:-6),y2+4);angle+=extent});legend(ctx,w,data.map(([l],i)=>[l,colors[i%colors.length]]),86)}
  function workload(canvas,rows){const title='حجم کار فعال به تفکیک متولی';if(!rows.length)return empty(canvas,title);rows=rows.slice(0,10);const {ctx,w,h}=frame(canvas,title),left=62,right=w-190,top=58,bottom=h-92,max=Math.max(...rows.map(([,p])=>Object.values(p).reduce((a,b)=>a+b,0)),1),segments=[['فوری','#d1495b'],['کم','#8b95a1'],['متوسط','#f0b429']],gap=18,bw=Math.max(50,Math.min(90,((right-left)-gap*(rows.length+1))/rows.length)),scale=(bottom-top)/max;for(let step=0;step<=5;step++){const y=bottom-(bottom-top)*step/5;ctx.strokeStyle='#edf2f0';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillStyle='#879a91';ctx.textAlign='right';ctx.font='12px "B Nazanin",Tahoma';ctx.fillText(fa(Math.round(max*step/5)),left-8,y+4)}let x=left+Math.max(0,(right-left-(rows.length*bw+(rows.length+1)*gap))/2)+gap;for(const [owner,parts] of rows){let y=bottom;for(const [label,color] of segments){const value=parts[label]||0,height=value*scale;if(height){ctx.fillStyle=color;ctx.fillRect(x,y-height,bw,height);ctx.fillStyle='#222';ctx.textAlign='center';ctx.font='bold 12px "B Nazanin",Tahoma';ctx.fillText(fa(value),x+bw/2,y-height/2+4);y-=height}}ctx.fillStyle='#435b51';ctx.textAlign='center';ctx.font='12px "B Nazanin",Tahoma';ctx.fillText(shortName(owner),x+bw/2,bottom+19);x+=bw+gap}legend(ctx,w,segments,82)}
  function performance(canvas,rows,note){const title='عملکرد متولیان';if(!rows.length)return empty(canvas,title,'در بازه انتخاب‌شده رکورد آرشیو پیدا نشد',note);rows=rows.slice(0,10);const {ctx,w,h}=frame(canvas,title,note),left=62,right=w-190,top=note?76:58,bottom=h-88,max=Math.max(...rows.flatMap(r=>[r[1],r[2]]),1),gap=20,gw=Math.max(60,Math.min(104,((right-left)-gap*(rows.length+1))/rows.length)),bw=Math.max(22,Math.min(34,(gw-10)/2)),scale=(bottom-top-10)/max;for(let step=0;step<=5;step++){const y=bottom-(bottom-top)*step/5;ctx.strokeStyle='#edf2f0';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillStyle='#879a91';ctx.textAlign='right';ctx.font='12px "B Nazanin",Tahoma';ctx.fillText(fa(Math.round(max*step/5)),left-8,y+4)}let x=left+Math.max(0,(right-left-(rows.length*gw+(rows.length+1)*gap))/2)+gap;for(const [owner,delay,advance] of rows){const dh=delay*scale,ah=advance*scale;ctx.fillStyle='#c94f5d';ctx.fillRect(x+4,bottom-dh,bw,dh);ctx.fillStyle='#f0b429';ctx.fillRect(x+12+bw,bottom-ah,bw,ah);ctx.fillStyle='#435b51';ctx.textAlign='center';ctx.font='bold 12px "B Nazanin",Tahoma';if(delay)ctx.fillText(fa(delay),x+4+bw/2,bottom-dh-7);if(advance)ctx.fillText(fa(advance),x+12+bw+bw/2,bottom-ah-7);ctx.font='12px "B Nazanin",Tahoma';ctx.fillText(shortName(owner),x+gw/2,bottom+19);x+=gw+gap}legend(ctx,w,[['تاخیر','#c94f5d'],['تعجیل','#f0b429']],82)}
  function parseJalali(value){const bits=en(value||'').match(/\d+/g)?.map(Number);return bits?.length===3?bits:null}
  function renderPerformance(archive){const owner=$id('dashOwner')?.value||'همه',priority=$id('dashPriority')?.value||'همه',from=parseJalali($id('perfFrom')?.value),to=parseJalali($id('perfTo')?.value),toNumber=p=>p?p[0]*10000+p[1]*100+p[2]:null;let rows=archive.filter(t=>{if(owner!=='همه'&&norm(ownerName(t))!==norm(owner))return false;if(priority!=='همه'&&norm(t.priority)!==norm(priority))return false;if(!from&&!to)return true;const p=persianParts(t.due_date);if(!p)return false;const n=toNumber([p.y,p.m,p.d]);return(!from||n>=toNumber(from))&&(!to||n<=toNumber(to))});const grouped={};for(const t of rows){const name=ownerName(t)||'—';grouped[name]??={delay:0,advance:0};grouped[name].delay+=Number(t.delay_days||0);grouped[name].advance+=Number(t.advance_days||0)}const values=Object.entries(grouped).filter(([,v])=>v.delay||v.advance).map(([name,v])=>[name,v.delay,v.advance]).sort((a,b)=>(b[1]+b[2])-(a[1]+a[2]));performance($id('performanceChart'),values,`رکورد بر اساس تاریخ پایان: ${fa(rows.length)}`)}
  function render(){if(!$id('dashboardView')||$id('dashboardView').classList.contains('hidden'))return;refreshFilters();const [kanban,archive]=filtered(),active=kanban.filter(t=>norm(t.status)!=='انجام شده');renderCards(kanban,archive);let statuses=STATUS_ORDER.filter(s=>kanban.some(t=>norm(t.status)===s));bar($id('statusChart'),'وضعیت وظایف جاری',statuses,statuses.map(s=>kanban.filter(t=>norm(t.status)===s).length),['#4f6bed','#2e8b57','#8f63d2','#9aa7b3']);const priorities=PRIORITY_ORDER.filter(p=>active.some(t=>norm(t.priority)===p));pie($id('priorityChart'),'توزیع کارها بر اساس اولویت',priorities.map(p=>[p,active.filter(t=>norm(t.priority)===p).length]),['#d1495b','#f0b429','#7b61c8','#8b95a1']);const buckets=BUCKET_ORDER.filter(b=>active.some(t=>bucketOf(t)===b));pie($id('bucketChart'),'وضعیت دیرکرد و هشدار',buckets.map(b=>[b,active.filter(t=>bucketOf(t)===b).length]),['#c94f5d','#ee9b00','#7aa6d1','#8b95a1']);const names=[...new Set(active.map(ownerName).filter(Boolean))],ownerRows=names.map(name=>{const parts={فوری:0,کم:0,متوسط:0};active.filter(t=>norm(ownerName(t))===norm(name)).forEach(t=>{const key=PRIORITY_ORDER.includes(norm(t.priority))?norm(t.priority):'متوسط';parts[key]++});return[name,parts]}).sort((a,b)=>Object.values(b[1]).reduce((x,y)=>x+y,0)-Object.values(a[1]).reduce((x,y)=>x+y,0));workload($id('workloadChart'),ownerRows);renderPerformance(state.tasks.filter(t=>t.archived))}
  function openDashboardCalendar(id){state.dashboardDateTarget=id;state.dateInput='__dashboard_date__';const current=parseJalali($id(id).value),now=currentJalali(),p=current?{y:current[0],m:current[1],d:current[2]}:now;$id('calendarLabel').textContent=id==='perfFrom'?'از تاریخ':'تا تاریخ';$id('calYear').innerHTML=Array.from({length:16},(_,i)=>now.y-5+i).map(y=>`<option value="${y}">${fa(y)}</option>`).join('');$id('calMonth').innerHTML=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'].map((n,i)=>`<option value="${i+1}">${n}</option>`).join('');$id('calYear').value=p.y;$id('calMonth').value=p.m;fillCalendarDays();$id('calDay').value=p.d;$id('calendarDialog').showModal()}
  ['dashOwner','dashPriority','dashStatus','dashBucket'].forEach(id=>$id(id)?.addEventListener('change',render));$id('resetDashFilters')?.addEventListener('click',()=>{['dashOwner','dashPriority','dashStatus','dashBucket'].forEach(id=>$id(id).value='همه');render()});$id('applyPerf')?.addEventListener('click',render);$id('clearPerf')?.addEventListener('click',()=>{$id('perfFrom').value='';$id('perfTo').value='';render()});document.querySelectorAll('.dashboard-calendar-btn,.dashboard-performance-range .jalali-input').forEach(el=>el.addEventListener('click',()=>openDashboardCalendar(el.dataset.dashboardDate||el.id)));$id('setDateBtn')?.addEventListener('click',()=>{if(!state.dashboardDateTarget)return;const target=$id(state.dashboardDateTarget);target.value=fa(`${$id('calYear').value}/${String($id('calMonth').value).padStart(2,'0')}/${String($id('calDay').value).padStart(2,'0')}`);state.dashboardDateTarget=null;render()});$id('clearDateBtn')?.addEventListener('click',()=>{if(!state.dashboardDateTarget)return;$id(state.dashboardDateTarget).value='';state.dashboardDateTarget=null;render()});document.querySelector('#nav [data-view="dashboard"]')?.addEventListener('click',()=>requestAnimationFrame(render));let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(render,120)});window.renderDashboard=render;
})();
